// Human-facing explanations for developer configuration.  The catalog owns
// identity, validation and defaults; this module keeps the developer panel's
// copy focused on gameplay effect rather than implementation history.
const descriptions=Object.freeze({
 'economy.daily_wage_per_crew':'Sets the gold paid to each crew member for one in-game day. This feeds the ship running-cost calculation and therefore changes how quickly merchant wallets are consumed at sea.',
 'simulation.seconds_per_day':'Sets how many real simulation seconds make up one in-game day. This changes the time scale used by wages, maintenance, consumption and other daily rates.',
 'simulation.economic_tick_seconds':'Sets how often the economic systems review production, consumption, markets and orders. Smaller values make the economy react more frequently but require more work.',
 'simulation.physics_tick_seconds':'Sets the movement and collision update interval. Smaller values improve physical temporal resolution and can make sailing smoother, at the cost of more updates.',
 'procurement.base_urgency_seconds':'Sets the baseline urgency window used when buyers decide how strongly to pursue missing inputs. Shorter windows make procurement react sooner to shortages.',
 'scaling.reference_distance':'Defines the distance used as the baseline for map-scale calculations. Other travel and review timings are scaled relative to this many hexes.',
 'scaling.map_factor':'Multiplies distance-based timing and planning estimates to account for the size of the generated world. Higher values make long-distance activity receive proportionally more time.',
 'scaling.standard_ship_speed':'Sets the representative ship speed used when converting distances into expected travel times. It is a planning reference, not a direct speed override for every hull.',
 'scaling.safety_margin':'Multiplies route deadlines beyond the theoretical travel time. Higher values give voyages more tolerance for wind, routing and handling delays.',
 'ledger.base_max_age_seconds':'Sets the base age after which a ship\'s observed market information is treated as stale. Older reports are excluded from planning and investment decisions.',
 'logistics.base_queue_review_seconds':'Sets how often berth and dock queues are reviewed for changes. It affects service responsiveness, not the physical time already spent handling cargo.',
 'merchant.base_job_review_seconds':'Sets the baseline interval between merchant job searches. Shorter intervals let idle ships look for new work sooner.',
 'roads.feeder_radius':'Sets the maximum road-search radius used when connecting local industries and town tiles to their parent port during world generation.',
 'roads.mountain_height':'Sets the terrain height treated as mountainous for road placement. Higher values allow roads across more elevated terrain; lower values make mountains stronger barriers.',
 'roads.max_search_nodes':'Caps the number of terrain nodes a road search may examine. Higher values can find longer or more difficult connections but increase generation cost.',
 'logistics.cargo_handling_rate':'Sets how many cargo units can be moved per simulated second during loading and unloading. Pickups still transfer only complete units.',
 'merchant.minimum_profit':'Sets the minimum expected gold profit a merchant requires before accepting a trade. Increasing it filters out more marginal voyages.',
 'merchant.starting_wallet':'Sets the opening gold placed in each newly created merchant wallet. It is granted once when the simulation session starts and is not replenished.',
 'merchant.distance_cost':'Sets the gold cost estimated for each unit of travel when comparing trading opportunities. Higher values make distant trades less attractive.',
 'fleet.max_test_merchants':'Caps the number of merchant ships that the development simulation can create. It is a test-fleet limit, not a production fleet-growth rule.',
 'navigation.wind_persistence':'Sets how long a significant wind change must persist before a ship requests a route replan. Higher values prevent frequent replanning from short-lived changes.',
 'navigation.threat_threshold':'Sets the threat level at which a route is considered unsafe enough to trigger avoidance or replanning. It is compared with the configured maximum threat.',
 'threat.max_threat':'Sets the maximum value of the threat field used by patrol and route-safety calculations. It establishes the scale for all threat thresholds.',
 'threat.decay_rate':'Sets how quickly threat from old incidents falls each simulated second. Higher values make danger disappear sooner after the area is no longer reinforced.',
 'threat.frequency_half_life':'Sets how many simulated seconds are needed for the remembered frequency of a threat event to halve. Longer values preserve incident history for longer.',
 'threat.recency_window':'Sets the time window in which recent patrol observations receive full recency weight. Older patrol information is progressively less useful.',
 'threat.max_patrol_age':'Sets the oldest patrol report that can contribute protection. Reports beyond this age no longer reduce route threat.',
 'fleet.frigate_merchants_per_patrol':'Sets how many merchant ships a frigate patrol quota covers before another frigate is allocated. Lower values create denser frigate protection.',
 'fleet.war_galleon_merchants_per_patrol':'Sets how many merchant ships a war-galleon patrol quota covers. Lower values allocate heavy warships more frequently.',
 'fleet.first_rate_merchants_per_patrol':'Sets how many merchant ships a first-rate patrol quota covers. Lower values allocate the largest warships more frequently.',
 'rendering.industry_icon_pixels':'Sets the target display size of industry icons on the map. It changes presentation only and does not change industry placement or production.',
 'economy.scarcity_ratio':'Sets the stock-to-target ratio at or below which a market emits a critical scarcity signal. Lower values require a deeper shortage before the signal appears.',
 'economy.surplus_ratio':'Sets the stock-to-target ratio at or above which a market emits a surplus signal. Higher values require a larger excess before the signal appears.',
 'economy.default_elasticity':'Sets how strongly prices respond to a stock shortage or surplus when a commodity has no more specific elasticity value.',
 'navigation.wind_shift_degrees':'Sets the minimum change in wind direction that can begin a persistent-wind route replan. It works together with Wind persistence.',
 'rendering.industry_icon_fade_start':'Sets the map scale at which industry icons begin fading toward their low-detail presentation. It must be lower than the fade-end value.',
 'rendering.industry_icon_fade_end':'Sets the map scale at which industry icons finish fading out. It must be higher than the fade-start value.',
 'rendering.road_visibility_start':'Sets the map scale at which roads begin appearing. It affects visibility only, not the underlying road network.',
 'rendering.road_visibility_end':'Sets the map scale at which roads reach full visibility. It must be higher than the visibility-start value.',
 'rendering.road_detail_start':'Sets the map scale at which additional road detail begins appearing.',
 'rendering.road_detail_end':'Sets the map scale at which additional road detail reaches full visibility. It must be higher than the detail-start value.',
 'rendering.building_detail_start':'Sets the map scale at which detailed town and building rendering begins appearing.',
 'rendering.building_detail_end':'Sets the map scale at which detailed town and building rendering reaches full visibility. It must be higher than the detail-start value.',
 'provisions.refill_seconds':'Sets the time required for a ship at anchor to refill its water stores. Docking replenishes water immediately; this value controls only gradual anchorage replenishment.',
 'provisions.diversion_improvement':'Sets how much the route planner prefers a reachable port ahead on the current voyage when a ship must divert for water. Higher values discourage backtracking.',
 'merchant.turnaround_wait_seconds':'Sets how long an empty merchant may remain at a berth while waiting for its next-job decision. Unloading and already accepted transfers are not delayed by this timer.',
 'merchant.exploration_interval_voyages':'Sets how many completed merchant departures occur between exploration voyages. The exploration voyage targets a port missing from the ship\'s current knowledge.',
 'economy.port_starting_gold':'Sets the one-time population treasury grant assigned to each port when a new accounting session is initialized. It is not an ongoing income source.',
 'economy.industry_starting_gold':'Sets the one-time working capital assigned to each manufacturing instance when a new accounting session is initialized. Factories must later fund themselves through sales.',
 'economy.manufacturing_worker_share':'Sets the fraction of an eligible industry-owned manufactured-goods sale paid to the parent port as worker income. The remainder stays with the producing factory.',
 'investment.enabled':'Enables or disables autonomous port investment reviews. Disabling it does not cancel accepted material orders or projects already under construction.',
 'investment.review_interval_seconds':'Sets how often each port evaluates whether to begin another industry investment. Shorter intervals make decisions sooner but perform more reviews.',
 'investment.maximum_report_age_seconds':'Sets the oldest visiting-ship market report that an investment decision may use. Ports never read a remote live market through this setting.',
 'investment.shortage_persistence_seconds':'Sets how long a shortage must remain supported by distinct observations before a port treats it as a durable investment opportunity.',
 'investment.minimum_observations':'Sets the minimum number of distinct newer market observations required before an investment can be considered.',
 'investment.minimum_shortage_units':'Sets the minimum observed gap between funded demand and advertised supply required to qualify as a shortage worth investing in.',
 'investment.reserve_buffer_days':'Sets how many days of estimated town consumption the port protects before spending treasury funds on expansion.',
 'investment.minimum_reserve_gold':'Sets the absolute minimum gold the port treasury must keep protected from investment spending.',
 'investment.minimum_surplus_gold':'Sets the extra spendable gold a port must have after reserves, commitments and material bids before it may invest.',
 'investment.maximum_pending_projects':'Caps the number of material-acquisition stages and unfinished industry projects a port may have active at once.',
 'investment.maximum_factories_per_port':'Caps active, acquired and under-construction manufacturing instances at one port.',
 'investment.maximum_instances_per_type':'Caps how many instances of one manufacturing type a single port may own, including projects already accepted for construction.',
 'investment.minimum_input_buffer_fraction':'Sets the minimum observed fraction of an industry\'s configured input buffer that must be available before the port considers building it.',
 'investment.minimum_margin_fraction':'Sets the minimum expected revenue margin above cost recovery, after the worker share, required for an investment.',
 'investment.material_bid_multiplier':'Multiplies baseline commodity prices when the port caps its funded bids for construction materials.',
 'investment.maximum_reports_per_port':'Caps the number of copied remote market reports retained by each port. Oldest reports are discarded first.',
 'investment.priority.rum_distillery':'Sets the review priority for rum distillery investments. Lower numbers are considered first when several opportunities qualify.',
 'investment.priority.textile_mill':'Sets the review priority for textile mill investments. Lower numbers are considered first when several opportunities qualify.',
 'investment.priority.ironworks':'Sets the review priority for ironworks investments. Lower numbers are considered first when several opportunities qualify.',
 'investment.priority.cannon_foundry':'Sets the review priority for cannon foundry investments. Lower numbers are considered first when several opportunities qualify.',
 'investment.priority.cannonball_foundry':'Sets the review priority for cannonball foundry investments. Lower numbers are considered first when several opportunities qualify.',
 'industries.starting_secondary_32':'Sets the target number of distinct secondary-industry types placed when generating a 32 × 32 world. Terrain, density and available ports can leave the target unmet.',
 'industries.starting_secondary_64':'Sets the target number of distinct secondary-industry types placed when generating a 64 × 64 world. Terrain, density and available ports can leave the target unmet.',
 'industries.starting_secondary_128':'Sets the target number of distinct secondary-industry types placed when generating a 128 × 128 world. Terrain, density and available ports can leave the target unmet.',
 'industries.starting_secondary_256':'Sets the target number of distinct secondary-industry types placed when generating a 256 × 256 world. Terrain, density and available ports can leave the target unmet.',
 'industries.starting_secondary_512':'Sets the target number of distinct secondary-industry types placed when generating a 512 × 512 world. Terrain, density and available ports can leave the target unmet.'
});

const timingText={
 simulation_restart:'Takes effect when the simulation is restarted or a new world is generated.',
 new_world:'Takes effect when a new world is generated.',
 next_tick:'Takes effect on the next simulation tick.',
 next_frame:'Takes effect on the next rendering frame.'
};
export function configurationDescription(definition){
 const core=descriptions[definition.id]??definition.description??'Controls this setting.';
 const timing=timingText[definition.apply_mode]??'Takes effect according to its configuration scope.';
 const range=definition.type==='boolean'?'Allowed values: enabled or disabled.':definition.type==='enum'?`Allowed values: ${definition.options.join(', ')}.`:`Allowed range: ${definition.min}–${definition.max} ${definition.unit??'units'}; step ${definition.step}.`;
 return `${core} ${timing} ${range}`;
}
